solution.Solution.cs:
using System.Xml;
using System.Xml.Linq;

public record Package(string Name, string Version);
public record ProjectInfo(string? TargetFramework, bool IsExe, bool NullableEnabled, List<Package> Packages, List<string> References);

public static class ProjectReader
{
    public static ProjectInfo Read(string xml)
    {
        XDocument doc;
        try { doc = XDocument.Parse(xml); }
        catch (XmlException e) { throw new FormatException("not a valid project file", e); }

        string? Value(string name) => doc.Descendants(name).FirstOrDefault()?.Value.Trim();

        var packages = doc.Descendants("PackageReference")
            .Select(p => new Package(p.Attribute("Include")?.Value ?? "", p.Attribute("Version")?.Value ?? ""))
            .OrderBy(p => p.Name, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var references = doc.Descendants("ProjectReference")
            .Select(r => r.Attribute("Include")?.Value ?? "")
            .Select(path => Path.GetFileNameWithoutExtension(path.Replace('\\', '/').Split('/')[^1]))
            .ToList();

        return new ProjectInfo(
            Value("TargetFramework"),
            string.Equals(Value("OutputType"), "Exe", StringComparison.OrdinalIgnoreCase),
            string.Equals(Value("Nullable"), "enable", StringComparison.OrdinalIgnoreCase),
            packages,
            references);
    }

    public static List<string> Outdated(IEnumerable<ProjectInfo> projects, IReadOnlyDictionary<string, string> latest) =>
        projects.SelectMany(p => p.Packages)
            .Where(p => latest.TryGetValue(p.Name, out var newest)
                        && Version.TryParse(p.Version, out var have)
                        && Version.TryParse(newest, out var best)
                        && have < best)
            .Select(p => $"{p.Name}: {p.Version} -> {latest[p.Name]}")
            .Distinct()
            .Order(StringComparer.Ordinal)
            .ToList();
}

unitTests:
const string Cli = """
    <Project Sdk="Microsoft.NET.Sdk">
      <PropertyGroup>
        <OutputType>exe</OutputType>
        <TargetFramework>net9.0</TargetFramework>
        <Nullable>enable</Nullable>
      </PropertyGroup>
      <ItemGroup>
        <PackageReference Include="Spectre.Console" Version="0.49.1" />
        <PackageReference Include="CsvHelper" Version="30.0.1" />
        <ProjectReference Include="..\Budget.Core\Budget.Core.csproj" />
        <ProjectReference Include="../Shared/Shared.Utils.csproj" />
      </ItemGroup>
    </Project>
    """;
const string Core = """
    <Project Sdk="Microsoft.NET.Sdk">
      <PropertyGroup><TargetFramework>net8.0</TargetFramework></PropertyGroup>
      <ItemGroup>
        <PackageReference Include="CsvHelper" Version="30.0.1" />
        <PackageReference Include="Serilog" Version="9.0.0" />
        <PackageReference Include="Odd" />
      </ItemGroup>
    </Project>
    """;

Test("reading a project", () =>
{
    var p = ProjectReader.Read(Cli);
    CheckEq(p.TargetFramework, "net9.0");
    CheckEq((p.IsExe, p.NullableEnabled), (true, true));
    CheckEq(p.Packages.Select(x => $"{x.Name} {x.Version}"), new[] { "CsvHelper 30.0.1", "Spectre.Console 0.49.1" });
    CheckEq(p.References, new[] { "Budget.Core", "Shared.Utils" });
});

Test("a library project", () =>
{
    var p = ProjectReader.Read(Core);
    CheckEq((p.TargetFramework, p.IsExe, p.NullableEnabled), ("net8.0", false, false));
    CheckEq(p.Packages.Last(), new Package("Serilog", "9.0.0"));
    CheckEq(p.Packages[1], new Package("Odd", ""));
    CheckEq(ProjectReader.Read("<Project />").TargetFramework, null);
});

Test("outdated packages", () =>
{
    var latest = new Dictionary<string, string> { ["CsvHelper"] = "33.0.1", ["Serilog"] = "10.0.0", ["Spectre.Console"] = "0.49.1", ["Odd"] = "1.0" };
    var projects = new[] { ProjectReader.Read(Cli), ProjectReader.Read(Core) };
    CheckEq(ProjectReader.Outdated(projects, latest), new[] { "CsvHelper: 30.0.1 -> 33.0.1", "Serilog: 9.0.0 -> 10.0.0" });
});

Test("invalid XML", () =>
{
    try
    {
        ProjectReader.Read("<Project><oops></Project>");
        Check(false, "should throw");
    }
    catch (FormatException e)
    {
        Check(e.InnerException is System.Xml.XmlException, "keep the XmlException as the inner exception");
    }
});

